   190	static uint16_t sf32lb52_bt_get_le16(const uint8_t *data)
   191	{
   192	  return (uint16_t)data[0] | ((uint16_t)data[1] << 8);
   193	}
   194	
   195	static void sf32lb52_bt_put_le16(uint8_t *data, uint16_t value)
   196	{
   197	  data[0] = value & 0xff;
   198	  data[1] = value >> 8;
   199	}
