   201	static ssize_t sf32lb52_bt_h4_packet_len(const uint8_t *data, size_t len)
   202	{
   203	  uint16_t payload_len;
   204	
   205	  if (len < H4_HEADER_SIZE)
   206	    {
   207	      return 0;
   208	    }
   209	
   210	  switch (data[0])
   450	      case BT_HCI_OP_HOST_BUFFER_SIZE:
   451	      case BT_HCI_OP_SET_CTL_TO_HOST_FLOW:
   452	        *ret = sf32lb52_bt_synth_status_complete(priv, opcode);
   453	        return true;
   454	
   455	      default:
   456	        return false;
   457	    }
   458	}
