   460	static struct sf32lb52_bt_priv_s g_sf32lb52_bt_priv =
   461	{
   462	  .drv =
   463	    {
   464	      .head_reserve = H4_HEADER_SIZE,
   465	      .open         = sf32lb52_bt_open,
   466	      .send         = sf32lb52_bt_send,
   467	      .close        = sf32lb52_bt_close,
   468	    },
   469	};
