   471	static int sf32lb52_bt_recv_cb(uint8_t *data, uint16_t len)
   472	{
   473	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
   474	  ssize_t packet_len;
   475	  int ret;
   476	
   477	  if (data == NULL || len == 0)
   478	    {
   479	      return -EINVAL;
   480	    }
   481	
   482	  if (priv->drop_rx_until_tx)
   483	    {
   484	      return OK;
   485	    }
   486	
   487	  if (priv->rxlen + len > sizeof(priv->rxbuf))
   488	    {
   489	      syslog(LOG_ERR,
   490	             "sf32lb52 bth4 rx overflow: pending=%lu incoming=%u\n",
   491	             (unsigned long)priv->rxlen,
   492	             len);
   493	      priv->rxlen = 0;
   494	    }
   495	
   496	  memcpy(&priv->rxbuf[priv->rxlen], data, len);
   497	  priv->rxlen += len;
   498	
   499	#if SF32LB52_BT_TRACE
   500	  syslog(LOG_INFO,
   501	         "sf32lb52 bth4 recv: len=%u pending=%lu first=%02x\n",
   502	         len, (unsigned long)priv->rxlen, priv->rxbuf[0]);
   503	#endif
   504	
   505	  ret = OK;
   506	
   507	  while (priv->rxlen > 0)
   508	    {
   509	      packet_len = sf32lb52_bt_h4_packet_len(priv->rxbuf, priv->rxlen);
   510	      if (packet_len == 0)
   511	        {
   512	          break;
   513	        }
   514	
   515	      if (packet_len < 0)
   516	        {
   517	          syslog(LOG_WARNING,
   518	                 "sf32lb52 bth4 drop invalid h4 type=%02x pending=%lu\n",
   519	                 priv->rxbuf[0],
   520	                 (unsigned long)priv->rxlen);
   521	          memmove(priv->rxbuf, &priv->rxbuf[1], priv->rxlen - 1);
   522	          priv->rxlen--;
   523	          ret = -EINVAL;
   524	          continue;
   525	        }
   526	
   527	      if ((size_t)packet_len > priv->rxlen)
   528	        {
   529	          break;
   530	        }
   531	
   532	      ret = sf32lb52_bt_forward_packet(priv, priv->rxbuf,
   533	                   (size_t)packet_len);
   534	
   535	      priv->rxlen -= (size_t)packet_len;
   536	      if (priv->rxlen > 0)
   537	        {
   538	          memmove(priv->rxbuf,
   539	                  &priv->rxbuf[packet_len],
   540	                  priv->rxlen);
   541	        }
   542	    }
   543	
   544	  return ret;
   545	}
