   547	static int sf32lb52_bt_send(struct bt_driver_s *drv,
   548	                            enum bt_buf_type_e type,
   549	                            void *data, size_t len)
   550	{
   551	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
   552	  uint8_t *hdr = (uint8_t *)data - drv->head_reserve;
   553	  uint16_t opcode;
   554	  int ret;
   555	
   556	  switch (type)
   557	    {
   558	      case BT_CMD:
   559	        *hdr = H4_CMD;
   560	        break;
   561	      case BT_ACL_OUT:
   562	        *hdr = H4_ACL;
   563	        break;
   564	      case BT_ISO_OUT:
   565	        *hdr = H4_ISO;
   566	        break;
   567	      default:
   568	        syslog(LOG_ERR, "sf32lb52 bth4 send: bad type %u\n",
   569	               (unsigned int)type);
   570	        return -EINVAL;
   571	    }
   572	
   573	  if (type == BT_CMD && len >= sizeof(struct bt_hci_cmd_hdr_s))
   574	    {
   575	      opcode = sf32lb52_bt_get_le16(data);
   576	      if (sf32lb52_bt_emulate_cmd(priv, opcode, &ret))
   577	        {
   578	          if (ret < 0)
   579	            {
   580	              syslog(LOG_ERR, "sf32lb52 bth4 send: emulate 0x%04x "
   581	                     "failed: %d\n", opcode, ret);
   582	              return ret;
   583	            }
   584	
   585	          return len;
   586	        }
   587	
   588	      ret = sf32lb52_bt_ensure_controller_enabled(opcode);
   589	      if (ret < 0)
   590	        {
   591	          return ret;
   592	        }
   593	    }
   594	  else
   595	    {
   596	      ret = sf32lb52_bt_ensure_controller_enabled(0);
   597	      if (ret < 0)
   598	        {
   599	          return ret;
   600	        }
   601	    }
   602	
   603	  priv->drop_rx_until_tx = false;
   604	
   605	  if (SF32LB52_BT_TRACE && type == BT_ACL_OUT)
   606	    {
   607	      syslog(LOG_INFO,
   608	             "sf32lb52 bth4 tx: type=%u len=%lu h4=%02x acl=%02x %02x %02x %02x\n",
   609	             (unsigned int)type,
   610	             (unsigned long)(len + drv->head_reserve),
   611	             hdr[0],
   612	             len >= 1 ? hdr[1] : 0,
   613	             len >= 2 ? hdr[2] : 0,
   614	             len >= 3 ? hdr[3] : 0,
   615	             len >= 4 ? hdr[4] : 0);
   616	    }
   617	
   618	  ret = sf32lb52_host_send_packet(hdr, len + drv->head_reserve);
   619	  if (ret < 0)
   620	    {
   621	      syslog(LOG_ERR, "sf32lb52 bth4 send: host_send_packet failed: %d\n",
   622	             ret);
   623	      return ret;
   624	    }
   625	
   626	  return len;
   627	}
   628	
   629	static int sf32lb52_bt_ensure_controller_enabled(uint16_t opcode)
   630	{
   631	  int ret;
   632	
   633	  ret = sf32lb52_bt_controller_enable();
   634	  if (ret < 0)
   635	    {
   636	      syslog(LOG_ERR,
   637	             "sf32lb52 bth4 controller enable failed before opcode=0x%04x: %d\n",
   638	             opcode,
   639	             ret);
   640	    }
   641	
   642	  return ret;
   643	}
