   645	static int sf32lb52_bt_open(struct bt_driver_s *drv)
   646	{
   647	  int ret;
   648	
   649	  (void)drv;
   650	
   651	  g_sf32lb52_bt_priv.rxlen = 0;
   652	  g_sf32lb52_bt_priv.drop_rx_until_tx = true;
   653	
   654	  ret = sf32lb52_bt_controller_init();
   655	  if (ret < 0)
   656	    {
   657	      syslog(LOG_ERR, "sf32lb52 bth4: controller_init failed: %d\n", ret);
   658	      return ret;
   659	    }
   660	
   661	  ret = sf32lb52_hci_register_callback(sf32lb52_bt_recv_cb);
   662	  if (ret < 0)
   663	    {
   664	      syslog(LOG_ERR, "sf32lb52 bth4: register rx callback failed: %d\n",
   665	             ret);
   666	      return ret;
   667	    }
   668	
   669	  return OK;
   670	}
