   672	static void sf32lb52_bt_close(struct bt_driver_s *drv)
   673	{
   674	  int ret;
   675	
   676	  (void)drv;
   677	
   678	  g_sf32lb52_bt_priv.rxlen = 0;
   679	
   680	  /* Full deinit (not just disable) so that the next open re-initialises
   681	   * the IPC queue from a clean state.  Without deinit, controller_init
   682	   * is skipped on re-open (status != IDLE), and LCPU's ring-buffer
   683	   * read pointer (reset on power-on) diverges from HCPU's stale write
   684	   * pointer, causing all HCI commands to be silently dropped. */
   685	  ret = sf32lb52_bt_controller_deinit();
   686	  if (ret < 0)
   687	    {
   688	      wlerr("Failed to deinit HCI controller: %d\n", ret);
   689	    }
   690	}
